<script>document.querySelectorAll('.schedule-group').forEach(group=>{const slots=group.querySelector('.schedule-slots'),button=group.querySelector('.add-schedule-slot, .add-cleaning-slot'),template=group.querySelector('template'),isCleaning=group.classList.contains('schedule-group-cleaning');if(!button)return;const fill=select=>{const phone=select.parentElement.querySelector('.schedule-phone');if(phone)phone.value=select.options[select.selectedIndex]?.dataset.phone||'Namba haijawekwa'};slots.querySelectorAll('select').forEach(select=>{select.addEventListener('change',()=>fill(select));fill(select)});button.addEventListener('click',()=>{const row=document.createElement('div');row.className='schedule-person';row.innerHTML=`<select name="${button.dataset.name}" required><option value="">${button.dataset.placeholder}</option>${template.innerHTML}</select>${isCleaning?'':'<input class="schedule-phone" type="text" readonly placeholder="Namba ya simu">'}<button type="button" class="button secondary remove-schedule-slot">Ondoa</button>`;const select=row.querySelector('select');select.addEventListener('change',()=>fill(select));fill(select);row.querySelector('.remove-schedule-slot').addEventListener('click',()=>row.remove());slots.append(row)})});const elderPhones=Object.fromEntries([...document.querySelectorAll('#elder-options option')].map(option=>[option.value,option.dataset.phone||'']));const setupElder=row=>{const name=row.querySelector('.elder-name'),phone=row.querySelector('.elder-phone');name.addEventListener('input',()=>{if(elderPhones[name.value])phone.value=elderPhones[name.value]})};document.querySelectorAll('.schedule-group-elder .schedule-person').forEach(setupElder);document.querySelector('.add-elder-slot')?.addEventListener('click',()=>{const row=document.createElement('div');row.className='schedule-person';row.innerHTML='<input class="elder-name" name="elder_names[]" list="elder-options" placeholder="Andika jina la mzee wa kanisa" required><input class="elder-phone" name="elder_phones[]" type="text" placeholder="Namba ya simu"><button type="button" class="button secondary remove-schedule-slot">Ondoa</button>';setupElder(row);row.querySelector('.remove-schedule-slot').addEventListener('click',()=>row.remove());document.querySelector('.schedule-group-elder .schedule-slots').append(row)});</script>

