<script>
document.addEventListener('DOMContentLoaded',()=>{
  const toolbar=document.querySelector('.member-filters'), cards=[...document.querySelectorAll('.member-row')];
  if(!toolbar||!cards.length)return;
  const joinedDates=@json($members->map(fn ($member) => optional($member->joined_church_at)->format('Y-m-d') ?? optional($member->created_at)->format('Y-m-d'))->values());
  const years=joinedDates.map(date=>(date||'').slice(0,4));
  cards.forEach((card,index)=>{card.dataset.year=years[index]||'';card.dataset.joinedDate=joinedDates[index]||''});
  const year=document.createElement('select'); year.id='memberYearFilter';
  year.innerHTML='<option value="">Mwaka wote</option>'+[...new Set(years.filter(Boolean))].sort().reverse().map(value=>`<option value="${value}">${value}</option>`).join('');
  toolbar.append(year);
  const baseFilter=window.filterMembers;
  const summary=document.createElement('div'); summary.className='card muted'; summary.style.marginBottom='16px'; toolbar.after(summary);
  const renderWeeklySummary=()=>{const selected=year.value||years.sort().reverse()[0], grouped={};cards.filter(card=>card.dataset.year===selected).forEach(card=>{const date=new Date(card.dataset.joinedDate+'T00:00:00'),month=date.toLocaleString('sw-TZ',{month:'long'}),week=Math.min(5,Math.floor((date.getDate()-1)/7)+1);grouped[month]??=[0,0,0,0,0];grouped[month][week-1]++});summary.innerHTML=selected?`<strong>Walioingia mwaka ${selected}</strong><br>${Object.keys(grouped).length?Object.entries(grouped).map(([month,weeks])=>`<div class="record"><strong>${month}</strong><br>Wiki ya 1: ${weeks[0]} &nbsp; | &nbsp; Wiki ya 2: ${weeks[1]} &nbsp; | &nbsp; Wiki ya 3: ${weeks[2]} &nbsp; | &nbsp; Wiki ya 4: ${weeks[3]}${weeks[4]?` &nbsp; | &nbsp; Wiki ya 5: ${weeks[4]}`:''}</div>`).join(''):'Hakuna mshirika aliyeingia mwaka huu.'}`:'Chagua mwaka kuona walioingia kwa wiki.'};
  window.filterMembers=()=>{baseFilter();cards.forEach(card=>{if(year.value&&card.dataset.year!==year.value)card.style.display='none'});renderWeeklySummary()};
  renderWeeklySummary();
  year.addEventListener('change',window.filterMembers);
});
</script>

