<script>const officeBase='{{url('/church-office/members')}}';function show(id,b){document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.nav').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');b.classList.add('active')}function openModal(id){document.getElementById(id).classList.add('open')}function closeModal(id){document.getElementById(id).classList.remove('open')}function filterMembers(){const q=document.getElementById('memberSearch').value.toLowerCase(),filter=document.getElementById('memberFilter').value;document.querySelectorAll('.member-row').forEach(card=>{const matchesSearch=card.dataset.search.includes(q),gender=card.dataset.gender,marital=card.dataset.maritalStatus,studying=card.dataset.studying==='yes',movedIn=card.dataset.movedIn==='yes';const matchesFilter=!filter||(filter==='moved-in'&&movedIn)||(filter==='studying'&&studying)||(filter==='male'&&gender==='male')||(filter==='female'&&gender==='female')||(filter==='widowed'&&marital==='widowed')||(filter==='married-male'&&marital==='married'&&gender==='male')||(filter==='married-female'&&marital==='married'&&gender==='female');card.style.display=matchesSearch&&matchesFilter?'':'none'})}function dateValue(value){return value?String(value).slice(0,10):''}function editMember(m){let f=document.getElementById('editMemberForm');f.action=officeBase+'/'+m.id;editName.value=m.name||'';editMemberId.value=m.member_id||'';editEmail.value=m.email||'';editPhone.value=m.phone||'';editGender.value=m.gender||'';editDob.value=dateValue(m.dob);editAddress.value=m.address||'';editStreetName.value=m.street_name||'';editWard.value=m.ward||'';editMaritalStatus.value=m.marital_status||'';editSpouseNames.value=m.spouse_names||'';editChildrenCount.value=m.children_count??'';editSavedDate.value=dateValue(m.saved_date);editBaptismDate.value=dateValue(m.baptism_date);editEducation.value=m.education||'';editService.value=m.service||'';openModal('edit-member')}function assignDept(id,name){assignTitle.textContent='Weka '+name+' kwenye idara';assignDeptForm.action=officeBase+'/'+id+'/departments';openModal('assign-dept')}function viewDepartment(name,members){departmentTitle.textContent='Washirika wa '+name;departmentList.innerHTML=members.length?members.map(m=>`<article class="member-card"><div class="member-photo">${m.avatar?`<img src="{{asset('storage')}}/${m.avatar}">`:(m.name||'?').charAt(0)}</div><div class="member-details"><strong>${m.name}</strong><span class="member-role">${m.role==='kiongozi'?'Kiongozi':'Mshirika'}</span><small>✉ ${m.email||''}</small><small>☎ ${m.phone||'Namba haijawekwa'}</small></div></article>`).join(''):'<p class="muted">Hakuna mshirika kwenye idara hii.</p>';openModal('department-members')}</script></body></html>
